KEYWORDS = {'let', 'print'}
def tokenize(src):
    tokens = []
    i = 0
    while i < len(src):
        char = src[i]
        if char == ' ' or char == '\t':
            i = i + 1
        elif char.isdigit():
            lexeme = ''
            while i < len(src) and src[i].isdigit():
                lexeme = lexeme + src[i]
                i = i + 1
            tokens.append(('NUM', lexeme))
        elif char.isalpha() or char == '_':
            lexeme = ''
            while i < len(src) and (src[i].isalnum() or src[i] == '_'):
                lexeme = lexeme + src[i]
                i = i + 1
            if lexeme in KEYWORDS:
                tokens.append(('KEYWORD', lexeme))
            else:
                tokens.append(('ID', lexeme))
        elif char in '+-*/=':
            tokens.append(('OP', char))
            i = i + 1
        elif char == '(':
            tokens.append(('LPAREN', char))
            i = i + 1
        elif char == ')':
            tokens.append(('RPAREN', char))
            i = i + 1
        else:
            tokens.append(('ERROR', char))
            i = i + 1
    return tokens
print(tokenize("let x = 42"))

